  function v3Save(overrides: Partial<SaveDataV3> = {}): SaveDataV3 {
    return {
      version: 3,
      seed: 1337,
      changes: [[42, 0]],
      inventorySlots: [{ id: "dirt", count: 3 }],
      selectedSlot: 0,
      player: { x: 1, y: 2, z: 3 },
      ...overrides
    };
  }

  test("migrateSaveV3toV4 is a pure version bump leaving blockEntities absent", () => {
