    const out = serializeContainers(
      new Map<number, InventorySlot[]>([
        [100, full],
        [200, empty]
      ])
    );
    expect(out).toHaveLength(1);
    expect(out[0].index).toBe(100);
    expect(out[0].slots[0]).toEqual({ id: "dirt", count: 5, durability: undefined });
