  state.inventory[slot] = createSlot("food", 2);
  state.selectedSlot = slot;
  state.hunger = 5;
  engine.consumeEvents();
  engine.dispatch({ type: "eatFood" });
  expect(engine.consumeEvents().some((event) => event.type === "ateFood")).toBe(true);

