  return {
    voidTimer: 0,
    regenTimer: 0,
    sprintDistanceBudget: 0,
    walkDistanceBudget: 0,
    jumpBudget: 0,
    stuckTimer: 0,
    hostileSpawnTimer: 0,
    daylightHudTimer: 0,
    debugHudTimer: 0,
    randomTickTimer: 0,
    breedTimer: 0
  };
}

/** Per-frame continuous input, owned by the input controller. */
export type FrameInput = {
  keys: ReadonlySet<string>;
  capsActive: boolean;
  leftMouseHeld: boolean;
  pointerLocked: boolean;
};

