    state.inventory = adjustSlotCount(state.inventory, slot.id, 1, state.selectedSlot) ?? state.inventory;
    return;
  }

  state.worldMeshDirty = true;
  emit({ type: "blockPlaced", blockId: slot.blockId, x: tx, y: ty, z: tz });
