12	  equippedArmor: EquippedArmor;
13	  selectedHotbarSlot: number;
14	  hotbarSlots: number;
15	  recipes: Recipe[];
16	  craftingStation: "furnace" | null;
17	  /** Contents of the open chest, or null when no chest is open. */
18	  container: InventorySlot[] | null;
19	  canCraft: (recipe: Recipe) => boolean;
20	  onSwapSlots: (fromIndex: number, toIndex: number) => void;
21	  /** Moves a slot across the inventory/chest boundary (chest indices offset by CONTAINER_SLOT_BASE). */
22	  onMoveStack: (fromIndex: number, toIndex: number) => void;
23	  onToggleEquipArmor: (index: number) => void;
24	  onCraft: (recipe: Recipe) => void;
25	};
26	
27	const STATION_LABELS: Record<NonNullable<Recipe["station"]>, string> = {
28	  furnace: "Furnace"
29	};
30	
31	/**
32	 * The survival inventory: armor column, 27-slot storage grid, hotbar row, and
33	 * a recipe book where every entry shows ingredient icons and the result.
34	 * Items move by clicking one slot and then another (click-to-swap); clicking
35	 * an armor item toggles equipping it instead.
36	 */
37	export default function InventoryPanel({
38	  inventory,
39	  equippedArmor,
40	  selectedHotbarSlot,
41	  hotbarSlots,
42	  recipes,
43	  craftingStation,
44	  container,
45	  canCraft,
46	  onSwapSlots,
47	  onMoveStack,
48	  onToggleEquipArmor,
49	  onCraft
50	}: InventoryPanelProps) {
51	  const [pendingIndex, setPendingIndex] = useState<number | null>(null);
52	  const { tooltip, bind } = useItemTooltip();
53	
54	  // While a chest is open, moves span both grids (chest slots are offset by
55	  // CONTAINER_SLOT_BASE); otherwise a swap stays within the player inventory.
56	  const slotAt = (index: number): InventorySlot | undefined => (index >= CONTAINER_SLOT_BASE ? container?.[index - CONTAINER_SLOT_BASE] : inventory[index]);
57	
58	  const onSlotClick = (index: number) => {
59	    const slot = slotAt(index);
60	    if (!slot) return;
61	    // Clicking armor in the player inventory equips it; chest slots only move.
62	    if (index < CONTAINER_SLOT_BASE && slot.kind === "armor" && slot.count > 0) {
63	      onToggleEquipArmor(index);
64	      setPendingIndex(null);
65	      return;
66	    }
67	
68	    if (pendingIndex === null) {
69	      setPendingIndex(index);
70	      return;
71	    }
72	    if (pendingIndex === index) {
73	      setPendingIndex(null);
74	      return;
75	    }
76	    (container ? onMoveStack : onSwapSlots)(pendingIndex, index);
77	    setPendingIndex(null);
78	  };
79	
80	  const isEquipped = (slot: InventorySlot) => slot.kind === "armor" && !!slot.id && equippedArmor[slot.armorSlot ?? "helmet"] === slot.id;
81	
82	  const renderSlot = (slot: InventorySlot, idx: number, extraClass = "") => {
83	    const isChest = idx >= CONTAINER_SLOT_BASE;
84	    const name = isChest ? `Chest slot ${idx - CONTAINER_SLOT_BASE + 1}` : `Slot ${idx + 1}`;
85	    return (
86	      <button
87	        key={`inv-slot-${idx}`}
88	        className={["inv-slot", extraClass, pendingIndex === idx ? "pending" : "", isEquipped(slot) ? "equipped" : ""].filter(Boolean).join(" ")}
89	        onClick={() => onSlotClick(idx)}
90	        {...bind(itemTooltipFor(slot))}
91	        aria-label={slot.id && slot.count > 0 ? `${name}: ${slot.label}` : `${name}: empty`}
92	      >
93	        <ItemIcon slot={slot} size={32} />
94	      </button>
95	    );
96	  };
97	
98	  const hotbar = inventory.slice(0, hotbarSlots);
99	  const storage = inventory.slice(hotbarSlots);
100	
101	  return (
102	    <div className="inventory-panel">
103	      <div className="inventory-columns">
104	        <div className="inventory-main">
105	          {container ? (
106	            <div className="chest-section">
107	              <div className="inventory-heading">Chest</div>
108	              <div className="inv-grid chest-grid" data-testid="chest-grid">
109	                {container.map((slot, i) => renderSlot(slot, CONTAINER_SLOT_BASE + i))}
110	              </div>
111	            </div>
112	          ) : null}
113	          <div className="inventory-heading">Inventory</div>
114	          <div className="inventory-upper">
115	            <div className="armor-column">
116	              {ARMOR_SLOTS.map((armorSlot) => {
117	                const equippedId = equippedArmor[armorSlot];
118	                const equippedIndex = equippedId ? inventory.findIndex((slot) => slot.id === equippedId && slot.count > 0) : -1;
119	                const equippedItem = equippedIndex >= 0 ? inventory[equippedIndex] : undefined;
120	                return (
121	                  <button
122	                    key={`armor-${armorSlot}`}
123	                    className={equippedItem ? "inv-slot armor-slot filled" : "inv-slot armor-slot"}
124	                    onClick={() => equippedIndex >= 0 && onToggleEquipArmor(equippedIndex)}
125	                    {...bind(equippedItem ? itemTooltipFor(equippedItem) : { title: `${ARMOR_SLOT_LABELS[armorSlot]} (empty)` })}
126	                    aria-label={equippedItem ? `${ARMOR_SLOT_LABELS[armorSlot]}: ${equippedItem.label}` : `${ARMOR_SLOT_LABELS[armorSlot]}: empty`}
127	                  >
128	                    {equippedItem ? (
129	                      <ItemIcon slot={equippedItem} size={32} />
130	                    ) : (
131	                      <span className="armor-ghost">
132	                        <PixelImg src={itemIconUrl(armorSlot)} alt="" size={32} aria-hidden />
133	                      </span>
134	                    )}
135	                  </button>
136	                );
137	              })}
138	            </div>
139	            <div className="inventory-hint">
140	              Click one slot, then another to move items.
141	              <br />
142	              Click armor to equip or unequip it.
143	            </div>
144	          </div>
145	          <div className="inv-grid storage" data-testid="storage-grid">
146	            {storage.map((slot, offset) => renderSlot(slot, offset + hotbarSlots))}
147	          </div>
148	          <div className="inv-grid hotbar-row" data-testid="hotbar-grid">
149	            {hotbar.map((slot, idx) => renderSlot(slot, idx, idx === selectedHotbarSlot ? "active" : ""))}
150	          </div>
151	        </div>
152	
153	        <div className="recipe-book">
154	          <div className="inventory-heading">Crafting</div>
155	          <div className="recipe-list">
156	            {recipes.map((recipe) => {
157	              const stationLocked = !!recipe.station && recipe.station !== craftingStation;
